ALTER TABLE public.proposal_approvals ADD COLUMN review_version integer;
-- Reviewer identity and review snapshot are immutable; no self-approval or stale decision.
CREATE OR REPLACE FUNCTION public.sales_proposal_approval_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE p proposals;c jsonb;reviewer jsonb;BEGIN
 SELECT * INTO p FROM proposals WHERE id=NEW.proposal_id FOR UPDATE;
 IF p.id IS NULL OR NEW.workspace_id IS DISTINCT FROM p.workspace_id THEN RAISE EXCEPTION 'Proposta indisponível.' USING ERRCODE='42501';END IF;
 IF auth.uid() IS NULL OR auth.role()='service_role' THEN RETURN NEW;END IF;
 c:=sales_access_context();
 IF TG_OP='INSERT' THEN
  IF NOT sales_record_context_access(c,'proposals',p.id,'update') OR p.status::text<>'in_review'
    OR NEW.status::text<>'pending' OR NEW.requested_by IS DISTINCT FROM auth.uid()
    OR NEW.reviewer_id IS NULL OR NEW.reviewer_id=auth.uid() THEN RAISE EXCEPTION 'Solicitação de aprovação inválida.' USING ERRCODE='42501';END IF;
  reviewer:=work_subject_context(p.workspace_id,NEW.reviewer_id);
  IF NOT sales_record_context_access(reviewer,'proposals',p.id,'approve') THEN RAISE EXCEPTION 'Revisor sem permissão para aprovar esta proposta.' USING ERRCODE='42501';END IF;
  IF EXISTS(SELECT 1 FROM proposal_approvals WHERE proposal_id=p.id AND status::text='pending') THEN RAISE EXCEPTION 'Já existe revisão pendente.' USING ERRCODE='40001';END IF;
  NEW.review_version:=p.version;NEW.decided_at:=NULL;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['status','comment','decided_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','comment','decided_at'])
    OR OLD.status::text<>'pending' OR NEW.status::text NOT IN('approved','rejected') THEN RAISE EXCEPTION 'Decisão imutável ou inválida.' USING ERRCODE='42501';END IF;
  IF NEW.status::text='rejected' AND p.status::text='draft' AND p.version IS DISTINCT FROM OLD.review_version AND sales_record_context_access(c,'proposals',p.id,'update') THEN
   NEW.decided_at:=clock_timestamp();RETURN NEW;
  END IF;
  IF OLD.reviewer_id IS DISTINCT FROM auth.uid() OR OLD.requested_by=auth.uid()
   OR p.status::text<>'in_review' OR p.version IS DISTINCT FROM OLD.review_version
   OR NOT sales_record_context_access(c,'proposals',p.id,'approve') THEN RAISE EXCEPTION 'Revisão não autorizada ou desatualizada.' USING ERRCODE='42501';END IF;
  NEW.decided_at:=clock_timestamp();
 END IF;RETURN NEW;
END $$;
CREATE TRIGGER zzzz_sales_approval BEFORE INSERT OR UPDATE ON public.proposal_approvals FOR EACH ROW EXECUTE FUNCTION public.sales_proposal_approval_guard();
CREATE OR REPLACE FUNCTION public.sales_proposal_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c jsonb:=sales_access_context();changed boolean;can_edit boolean;BEGIN
 IF auth.uid() IS NULL OR auth.role()='service_role' THEN RETURN NEW;END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status::text<>'draft' OR NEW.locked OR NEW.sent_at IS NOT NULL OR NEW.decided_at IS NOT NULL THEN RAISE EXCEPTION 'Crie a proposta em rascunho.' USING ERRCODE='42501';END IF;
  RETURN NEW;
 END IF;
 can_edit:=sales_record_context_access(c,'proposals',OLD.id,'update');
 -- Approval/sending authority cannot edit commercial fields or the source links.
 IF NOT can_edit AND (to_jsonb(NEW)-ARRAY['status','locked','sent_at','decided_at','updated_at','variables','public_token']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','locked','sent_at','decided_at','updated_at','variables','public_token']) THEN RAISE EXCEPTION 'Sem permissão de edição.' USING ERRCODE='42501';END IF;
 changed:=(NEW.title,NEW.body,NEW.total_amount,NEW.currency,NEW.expires_at,NEW.deal_id,NEW.contact_id,NEW.company_id,(NEW.variables-'document_hash'-'content_hash')) IS DISTINCT FROM (OLD.title,OLD.body,OLD.total_amount,OLD.currency,OLD.expires_at,OLD.deal_id,OLD.contact_id,OLD.company_id,(OLD.variables-'document_hash'-'content_hash'));
 IF NOT can_edit AND (NEW.variables-'document_hash'-'content_hash') IS DISTINCT FROM (OLD.variables-'document_hash'-'content_hash') THEN RAISE EXCEPTION 'Sem permissão de edição.' USING ERRCODE='42501';END IF;
 IF NEW.decided_at IS DISTINCT FROM OLD.decided_at THEN RAISE EXCEPTION 'Resposta do cliente imutável.' USING ERRCODE='42501';END IF;
 IF NEW.sent_at IS DISTINCT FROM OLD.sent_at AND NOT(NEW.status::text='sent' AND OLD.status::text IN('draft','approved')) THEN RAISE EXCEPTION 'Data de envio imutável.' USING ERRCODE='42501';END IF;
 IF NEW.version IS DISTINCT FROM OLD.version THEN RAISE EXCEPTION 'Versão calculada pelo servidor.' USING ERRCODE='42501';END IF;
 IF OLD.locked AND (to_jsonb(NEW)-ARRAY['status','decided_at','updated_at','public_token']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','decided_at','updated_at','public_token']) THEN RAISE EXCEPTION 'Proposta publicada está selada.' USING ERRCODE='42501';END IF;
 IF changed THEN
  IF NOT sales_record_context_access(c,'proposals',OLD.id,'update') THEN RAISE EXCEPTION 'Sem permissão de edição.' USING ERRCODE='42501';END IF;
  NEW.version:=OLD.version+1;NEW.status:='draft';
 END IF;
 IF NEW.status::text IS DISTINCT FROM OLD.status::text THEN
  IF NEW.status::text='approved' THEN
   IF OLD.status::text<>'in_review' OR NOT sales_record_context_access(c,'proposals',OLD.id,'approve') OR NOT EXISTS(SELECT 1 FROM proposal_approvals a WHERE a.proposal_id=OLD.id AND a.status::text='approved' AND a.reviewer_id=auth.uid() AND a.requested_by<>auth.uid() AND a.review_version=OLD.version) THEN RAISE EXCEPTION 'Aprovação interna obrigatória.' USING ERRCODE='42501';END IF;
  ELSIF NEW.status::text='sent' THEN
   IF NOT sales_context_access(c,OLD.workspace_id,'techsales.proposal_send','manage',ARRAY[coalesce(OLD.assigned_to,OLD.owner_id)]) OR NOT NEW.locked OR NEW.sent_at IS NULL THEN RAISE EXCEPTION 'Envio não autorizado.' USING ERRCODE='42501';END IF;
   IF EXISTS(SELECT 1 FROM proposal_approvals WHERE proposal_id=OLD.id AND status::text='pending') OR (EXISTS(SELECT 1 FROM proposal_approvals WHERE proposal_id=OLD.id) AND NOT EXISTS(SELECT 1 FROM proposal_approvals WHERE proposal_id=OLD.id AND status::text='approved' AND review_version=NEW.version)) THEN RAISE EXCEPTION 'Aprovação vigente obrigatória.' USING ERRCODE='42501';END IF;
   IF OLD.status::text NOT IN('draft','approved') OR (NEW.expires_at IS NOT NULL AND NEW.expires_at<=clock_timestamp()) THEN RAISE EXCEPTION 'Proposta indisponível para envio.' USING ERRCODE='42501';END IF;
   NEW.sent_at:=clock_timestamp();
   NEW.variables:=coalesce(NEW.variables,'{}')||jsonb_build_object('document_hash',encode(extensions.digest(jsonb_build_object('id',NEW.id,'title',NEW.title,'body',NEW.body,'total',NEW.total_amount,'currency',NEW.currency,'version',NEW.version,'sent_at',NEW.sent_at)::text,'sha256'),'hex'));
  ELSIF NEW.status::text='in_review' THEN
   IF NOT can_edit OR OLD.status::text<>'draft' OR OLD.locked THEN RAISE EXCEPTION 'Revisão não autorizada.' USING ERRCODE='42501';END IF;
  ELSIF NEW.status::text='draft' THEN
   IF OLD.locked OR (NOT can_edit AND NOT EXISTS(SELECT 1 FROM proposal_approvals WHERE proposal_id=OLD.id AND reviewer_id=auth.uid() AND status::text='rejected' AND review_version=OLD.version)) THEN RAISE EXCEPTION 'Retorno a rascunho não autorizado.' USING ERRCODE='42501';END IF;
   -- A canceled review always becomes stale, even if only the status changed.
   IF OLD.status::text='in_review' AND NOT changed THEN NEW.version:=OLD.version+1;END IF;
  ELSIF NEW.status::text IN('accepted','rejected') THEN RAISE EXCEPTION 'A resposta do cliente exige o link público válido.' USING ERRCODE='42501';
  END IF;
 END IF;
 IF NEW.locked IS DISTINCT FROM OLD.locked AND NOT(NEW.locked AND NEW.status::text='sent') THEN RAISE EXCEPTION 'Selo imutável.' USING ERRCODE='42501';END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER zzzz_sales_proposal BEFORE INSERT OR UPDATE ON public.proposals FOR EACH ROW EXECUTE FUNCTION public.sales_proposal_guard();
CREATE OR REPLACE FUNCTION public.sales_proposal_invalidate_review()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$BEGIN
 IF NEW.version IS DISTINCT FROM OLD.version THEN UPDATE proposal_approvals SET status='rejected',comment='Conteúdo alterado; revisão invalidada.',decided_at=clock_timestamp() WHERE proposal_id=NEW.id AND status::text='pending' AND review_version IS DISTINCT FROM NEW.version;END IF;RETURN NEW;END $$;
CREATE TRIGGER sales_proposal_revision AFTER UPDATE ON public.proposals FOR EACH ROW EXECUTE FUNCTION public.sales_proposal_invalidate_review();
CREATE POLICY sales_approval_request ON public.proposal_approvals FOR INSERT TO authenticated WITH CHECK(requested_by=auth.uid() AND status::text='pending' AND EXISTS(SELECT 1 FROM public.proposals p WHERE p.id=proposal_id AND p.workspace_id=proposal_approvals.workspace_id AND public.sales_context_access((SELECT public.sales_access_context()),p.workspace_id,'techsales.proposals','update',ARRAY[coalesce(p.assigned_to,p.owner_id)])));
CREATE POLICY sales_approval_decision ON public.proposal_approvals FOR UPDATE TO authenticated USING(reviewer_id=auth.uid() AND requested_by<>auth.uid() AND EXISTS(SELECT 1 FROM public.proposals p WHERE p.id=proposal_id AND public.sales_context_access((SELECT public.sales_access_context()),p.workspace_id,'techsales.proposals','approve',ARRAY[coalesce(p.assigned_to,p.owner_id)]))) WITH CHECK(reviewer_id=auth.uid() AND requested_by<>auth.uid());
CREATE POLICY sales_proposal_decision ON public.proposals FOR UPDATE TO authenticated USING(public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.proposals','approve',ARRAY[coalesce(assigned_to,owner_id)])) WITH CHECK(public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.proposals','approve',ARRAY[coalesce(assigned_to,owner_id)]));
CREATE POLICY sales_proposal_publish ON public.proposals FOR UPDATE TO authenticated USING(public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.proposal_send','manage',ARRAY[coalesce(assigned_to,owner_id)])) WITH CHECK(public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.proposal_send','manage',ARRAY[coalesce(assigned_to,owner_id)]));
CREATE OR REPLACE FUNCTION public.sales_proposal_request(p_id uuid,p_reviewer uuid,p_comment text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE p record;a uuid;v_reviewer uuid:=p_reviewer;BEGIN
 IF NOT sales_record_access('proposals',p_id,'update') THEN RAISE EXCEPTION 'Proposta indisponível.' USING ERRCODE='42501';END IF;
 SELECT id,workspace_id,status,locked,version,assigned_to,owner_id INTO p FROM proposals WHERE id=p_id FOR UPDATE;
 IF p.id IS NULL OR p.locked OR p.status::text<>'draft' THEN RAISE EXCEPTION 'Somente rascunhos podem ser enviados à revisão.';END IF;
 IF v_reviewer IS NULL THEN RAISE EXCEPTION 'Selecione um revisor ativo para a proposta.';END IF;
 UPDATE proposals SET status='in_review' WHERE id=p.id;
 INSERT INTO proposal_approvals(workspace_id,proposal_id,requested_by,reviewer_id,comment,status,review_version) VALUES(p.workspace_id,p.id,auth.uid(),v_reviewer,left(p_comment,2000),'pending',p.version) RETURNING id INTO a;
 RETURN jsonb_build_object('ok',true,'approvalId',a);
END $$;
CREATE OR REPLACE FUNCTION public.sales_proposal_decide(p_approval uuid,p_decision text,p_comment text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE a record;p record;BEGIN
 IF p_decision NOT IN('approved','rejected') THEN RAISE EXCEPTION 'Decisão inválida.';END IF;
 SELECT proposal_id INTO a FROM proposal_approvals WHERE id=p_approval;
 SELECT id,version,status INTO p FROM proposals WHERE id=a.proposal_id FOR UPDATE;
 SELECT * INTO a FROM proposal_approvals WHERE id=p_approval FOR UPDATE;
 IF a.id IS NULL OR p.id IS NULL OR NOT sales_record_access('proposals',p.id,'approve') THEN RAISE EXCEPTION 'Revisão indisponível.' USING ERRCODE='42501';END IF;
 UPDATE proposal_approvals SET status=p_decision::proposal_approval_status,comment=left(p_comment,2000),decided_at=clock_timestamp() WHERE id=a.id;
 UPDATE proposals SET status=CASE WHEN p_decision='approved' THEN 'approved'::proposal_status ELSE 'draft'::proposal_status END WHERE id=p.id;
 RETURN jsonb_build_object('ok',true);
END $$;
CREATE OR REPLACE FUNCTION public.proposal_publish_with_esign(p_id uuid,p_hash text,p_sent_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE p record;h text;ts timestamptz:=clock_timestamp();BEGIN
 PERFORM sales_area_authorize('techsales.proposal_send','manage');
 IF NOT sales_record_access('proposals',p_id,'view') THEN RAISE EXCEPTION 'Proposta indisponível.' USING ERRCODE='42501';END IF;
 SELECT id,workspace_id,title,body,total_amount,currency,version,status,locked,expires_at,esign_document_id,variables INTO p FROM proposals WHERE id=p_id FOR UPDATE;
 IF p.id IS NULL OR p.locked OR p.status::text NOT IN('draft','approved') OR (p.expires_at IS NOT NULL AND p.expires_at<ts) THEN RAISE EXCEPTION 'Proposta não pode ser publicada.';END IF;
 IF EXISTS(SELECT 1 FROM proposal_approvals WHERE proposal_id=p.id) AND NOT EXISTS(SELECT 1 FROM proposal_approvals WHERE proposal_id=p.id AND status::text='approved' AND review_version=p.version) THEN RAISE EXCEPTION 'É necessária nova aprovação do conteúdo atual.';END IF;
 IF EXISTS(SELECT 1 FROM proposal_approvals WHERE proposal_id=p.id AND status::text='pending') THEN RAISE EXCEPTION 'A revisão ainda está pendente.';END IF;
 h:=encode(extensions.digest(jsonb_build_object('id',p.id,'title',p.title,'body',p.body,'total',p.total_amount,'currency',p.currency,'version',p.version,'sent_at',ts)::text,'sha256'),'hex');
 IF p.esign_document_id IS NOT NULL THEN PERFORM contract_esign_manage('send',p.esign_document_id,'{}');END IF;
 UPDATE proposals SET status='sent',sent_at=ts,locked=true,variables=coalesce(p.variables,'{}')||jsonb_build_object('document_hash',h) WHERE id=p.id RETURNING variables->>'document_hash' INTO h;
 RETURN jsonb_build_object('ok',true,'contentHash',h);
END $$;
REVOKE ALL ON FUNCTION public.sales_proposal_request(uuid,uuid,text),public.sales_proposal_decide(uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sales_proposal_request(uuid,uuid,text),public.sales_proposal_decide(uuid,text,text) TO authenticated;
REVOKE ALL ON FUNCTION public.sales_proposal_guard(),public.sales_proposal_approval_guard(),public.sales_proposal_invalidate_review() FROM PUBLIC,anon,authenticated;

