CREATE POLICY sales_delete ON public.workflow_send_policies FOR DELETE TO authenticated USING(public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','view',ARRAY[]::uuid[]));
