-- Legacy callable ports must retain actual caller RLS, selected workspace and matrix actions.
CREATE OR REPLACE FUNCTION public.global_search_candidate_ids(_entity text, _q text, _limit integer DEFAULT 60)
 RETURNS SETOF uuid
 LANGUAGE plpgsql
 STABLE SECURITY INVOKER
 SET search_path TO 'public'
AS $function$
DECLARE
  p text;
  lim int := least(greatest(coalesce(_limit, 60), 1), 200);
BEGIN
  IF auth.uid() IS NULL OR length(trim(coalesce(_q, ''))) < 2 THEN
    RETURN;
  END IF;
  p := '%' || replace(replace(replace(trim(_q), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  IF _entity = 'activity' THEN
    RETURN QUERY SELECT a.id FROM activities a
      WHERE a.subject ILIKE p AND a.workspace_id IN (SELECT current_user_workspaces())
      LIMIT lim;
  ELSIF _entity = 'contact' THEN
    RETURN QUERY SELECT c.id FROM contacts c
      WHERE (c.first_name ILIKE p OR c.last_name ILIKE p OR c.email ILIKE p)
        AND c.workspace_id IN (SELECT current_user_workspaces())
      LIMIT lim;
  ELSIF _entity = 'company' THEN
    RETURN QUERY SELECT c.id FROM companies c
      WHERE (c.name ILIKE p OR c.domain ILIKE p)
        AND c.workspace_id IN (SELECT current_user_workspaces())
      LIMIT lim;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.company_portfolio_owner(_company_id uuid)
 RETURNS TABLE(owner_id uuid, owner_name text)
 LANGUAGE sql
 STABLE SECURITY INVOKER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(c.assigned_to, c.owner_id), p.full_name
  FROM public.companies c
  LEFT JOIN public.profiles p ON p.id = coalesce(c.assigned_to, c.owner_id)
  WHERE c.id = _company_id
    AND public.is_workspace_member(c.workspace_id, auth.uid());
$function$;

CREATE OR REPLACE FUNCTION public.deal_visible_to_current_user(_deal uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$SELECT EXISTS(SELECT 1 FROM public.deals WHERE id=_deal AND deleted_at IS NULL)$$;
CREATE OR REPLACE FUNCTION public.rep_find_companies(_q text)
 RETURNS TABLE(id uuid, name text, other_owner boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT c.id, c.name,
         coalesce(c.assigned_to, c.owner_id) IS DISTINCT FROM auth.uid()
  FROM public.companies c
  WHERE public.rep_is_restricted() AND (public.sales_access_context()->'keys'?'techsales.companies_lookup.view.workspace') AND c.workspace_id=(public.sales_access_context()->>'workspace')::uuid
    AND length(trim(coalesce(_q, ''))) >= 3
    AND c.workspace_id IN (SELECT public.rep_restricted_workspaces())
    AND c.deleted_at IS NULL
    AND (c.name ILIKE '%' || trim(_q) || '%'
         OR regexp_replace(coalesce(c.cnpj, ''), '\D', '', 'g') =
            nullif(regexp_replace(_q, '\D', '', 'g'), ''))
  ORDER BY c.name
  LIMIT 8;
$function$;

CREATE OR REPLACE FUNCTION public.inbox_assign_conversation(p_channel text,p_id uuid,p_assignee uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE t text;w uuid;n integer;BEGIN
 t:=CASE p_channel WHEN 'whatsapp' THEN 'whatsapp_conversations' WHEN 'email' THEN 'email_threads' WHEN 'chat' THEN 'live_chat_sessions' END;
 IF t IS NULL OR NOT sales_record_access(t,p_id,'update') OR NOT sales_record_access(t,p_id,'assign') THEN RETURN false;END IF;
 EXECUTE format('SELECT workspace_id FROM public.%I WHERE id=$1 FOR UPDATE',t) INTO w USING p_id;
 IF w IS NULL OR (p_assignee IS NOT NULL AND NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=p_assignee AND status='active')) THEN RETURN false;END IF;
 EXECUTE format('UPDATE public.%I SET %I=$1 WHERE id=$2',t,CASE WHEN p_channel='chat' THEN 'assignee_id' ELSE 'assigned_to' END) USING p_assignee,p_id;
 GET DIAGNOSTICS n=ROW_COUNT;RETURN n=1;
END $$;
CREATE OR REPLACE FUNCTION public.link_contacts_by_email_domain(p_workspace uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY INVOKER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_count integer := 0;
  v_free text[] := ARRAY[
    'gmail.com','hotmail.com','outlook.com','outlook.com.br','live.com','msn.com',
    'yahoo.com','yahoo.com.br','ymail.com','icloud.com','me.com','mac.com',
    'aol.com','proton.me','protonmail.com','pm.me','zoho.com','gmx.com','mail.com',
    'uol.com.br','bol.com.br','terra.com.br','ig.com.br','globo.com','globomail.com',
    'r7.com','oi.com.br','superig.com.br'
  ];
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
  IF p_workspace IS DISTINCT FROM (sales_access_context()->>'workspace')::uuid THEN RAISE EXCEPTION 'Workspace inválido.' USING ERRCODE='42501';END IF;
  PERFORM sales_area_authorize('techsales.contacts','update');
  PERFORM sales_area_authorize('techsales.companies','view');

  WITH cand AS (
    SELECT c.id,
           lower(btrim(split_part(c.email, '@', 2))) AS dom
      FROM public.contacts c
     WHERE c.workspace_id = p_workspace
       AND c.deleted_at IS NULL
       AND c.company_id IS NULL
       AND c.email IS NOT NULL
       AND position('@' in c.email) > 0
  ),
  matched AS (
    SELECT cand.id,
           (SELECT CASE WHEN count(*)=1 THEN min(matches.id::text)::uuid END FROM (
             SELECT co.id FROM public.companies co WHERE co.workspace_id=p_workspace AND co.deleted_at IS NULL
               AND (lower(trim(coalesce(co.domain,'')))=cand.dom OR lower(split_part(regexp_replace(coalesce(co.website,''),'^https?://',''), '/',1)) IN(cand.dom,'www.'||cand.dom))
           ) matches) AS company_id
      FROM cand
     WHERE cand.dom <> '' AND NOT (cand.dom = ANY (v_free))
  ),
  upd AS (
    UPDATE public.contacts c
       SET company_id = m.company_id
      FROM matched m
     WHERE c.id = m.id AND m.company_id IS NOT NULL
    RETURNING c.id
  )
  SELECT count(*) INTO v_count FROM upd;

  RETURN v_count;
END;
$function$;

CREATE OR REPLACE FUNCTION public.seed_access_profiles(_workspace uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_admin UUID;
  v_manager UUID;
  v_member UUID;
  v_obj TEXT;
  v_tool TEXT;
  v_objects TEXT[] := ARRAY[
    'contacts','companies','leads','deals','tickets','tasks',
    'notes','calls','meetings','emails','activities','products','quotes'
  ];
  v_tools TEXT[] := ARRAY[
    'communicate','import','export','bulk_delete',
    'manage_workflows','manage_properties','manage_pipelines',
    'access_logs','manage_integrations','manage_billing','manage_users'
  ];
BEGIN
  IF auth.role()<>'service_role' AND auth.uid() IS NOT NULL THEN
    IF NOT is_workspace_member(_workspace,auth.uid()) OR _workspace IS DISTINCT FROM (sales_access_context()->>'workspace')::uuid
      OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=_workspace AND user_id=auth.uid() AND status='active' AND role::text IN('admin','owner'))
      OR NOT (sales_access_context()->'keys'?'system.users.manage.workspace') OR is_read_only_view() THEN RAISE EXCEPTION 'Gerenciamento de usuários não autorizado.' USING ERRCODE='42501';END IF;
  ELSIF auth.role() IS DISTINCT FROM 'service_role' AND session_user NOT IN('postgres','supabase_admin') THEN RAISE EXCEPTION 'Execução não autorizada.' USING ERRCODE='42501';END IF;
  IF EXISTS (SELECT 1 FROM public.access_profiles WHERE workspace_owner_id = _workspace AND is_system) THEN
    RETURN;
  END IF;

  INSERT INTO public.access_profiles (workspace_owner_id, name, description, is_system, base_role)
  VALUES (_workspace, 'Admin', 'Acesso completo a todos os recursos e configurações.', true, 'admin')
  RETURNING id INTO v_admin;

  INSERT INTO public.access_profiles (workspace_owner_id, name, description, is_system, base_role)
  VALUES (_workspace, 'Gestor', 'Gerencia equipe e pipelines, sem acesso a billing.', true, 'manager')
  RETURNING id INTO v_manager;

  INSERT INTO public.access_profiles (workspace_owner_id, name, description, is_system, base_role)
  VALUES (_workspace, 'Membro', 'Acesso operacional aos próprios registros.', true, 'member')
  RETURNING id INTO v_member;

  FOREACH v_obj IN ARRAY v_objects LOOP
    INSERT INTO public.access_profile_permissions (profile_id, object_key, view_scope, edit_scope, delete_scope, create_enabled)
    VALUES (v_admin,   v_obj, 'all',  'all',  'all',  true);
    INSERT INTO public.access_profile_permissions (profile_id, object_key, view_scope, edit_scope, delete_scope, create_enabled)
    VALUES (v_manager, v_obj, 'all',  'team', 'team', true);
    INSERT INTO public.access_profile_permissions (profile_id, object_key, view_scope, edit_scope, delete_scope, create_enabled)
    VALUES (v_member,  v_obj, 'team', 'own',  'own',  true);
  END LOOP;

  FOREACH v_tool IN ARRAY v_tools LOOP
    INSERT INTO public.access_profile_tools (profile_id, tool_key, enabled) VALUES (v_admin, v_tool, true);
    INSERT INTO public.access_profile_tools (profile_id, tool_key, enabled) VALUES (v_manager, v_tool,
      v_tool NOT IN ('manage_billing','manage_users','manage_integrations'));
    INSERT INTO public.access_profile_tools (profile_id, tool_key, enabled) VALUES (v_member, v_tool,
      v_tool IN ('communicate','export'));
  END LOOP;

  -- backfill from team_members.role (team_role: owner/admin/member) and user_roles
  UPDATE public.team_members tm
     SET access_profile_id = CASE
       WHEN tm.role::text = 'admin' THEN v_admin
       WHEN tm.role::text = 'owner' THEN v_admin
       ELSE v_member
     END
   WHERE tm.workspace_owner_id = _workspace AND tm.access_profile_id IS NULL;

  -- bump manager-role users (app_role) to Gestor profile
  UPDATE public.team_members tm
     SET access_profile_id = v_manager
   WHERE tm.workspace_owner_id = _workspace
     AND tm.access_profile_id = v_member
     AND EXISTS (
       SELECT 1 FROM public.user_roles ur
       WHERE ur.workspace_owner_id = _workspace
         AND ur.user_id = tm.member_user_id
         AND ur.role = 'manager'
     );
END;
$function$;

INSERT INTO public.permissions(key,module,resource,action,scope,label_pt,description,is_system) VALUES('techsales.companies_lookup.view.workspace','techsales','companies_lookup','view','workspace','Consultar referência de empresa em outra carteira','Exceção mínima: somente ID e nome, até oito resultados; não concede a ficha da empresa.',true) ON CONFLICT(key) DO NOTHING;

CREATE OR REPLACE FUNCTION public.contact_link_company_by_domain()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE dom text;target uuid;n integer;free text[]:=ARRAY['gmail.com','hotmail.com','outlook.com','outlook.com.br','live.com','msn.com','yahoo.com','yahoo.com.br','ymail.com','icloud.com','me.com','mac.com','aol.com','proton.me','protonmail.com','pm.me','zoho.com','gmx.com','mail.com','uol.com.br','bol.com.br','terra.com.br','ig.com.br','globo.com','globomail.com','r7.com','oi.com.br','superig.com.br'];BEGIN
 IF NEW.company_id IS NOT NULL OR NEW.workspace_id IS NULL OR NEW.email IS NULL OR position('@' in NEW.email)=0 THEN RETURN NEW;END IF;
 dom:=lower(trim(split_part(NEW.email,'@',2)));
 IF dom='' OR dom=ANY(free) THEN RETURN NEW;END IF;
 SELECT count(*),min(id::text)::uuid INTO n,target FROM companies WHERE workspace_id=NEW.workspace_id AND deleted_at IS NULL AND (lower(trim(coalesce(domain,'')))=dom OR lower(split_part(regexp_replace(coalesce(website,''),'^https?://',''), '/',1)) IN(dom,'www.'||dom));
 IF n=1 THEN NEW.company_id:=target;END IF;RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.contact_link_company_by_domain() FROM PUBLIC,anon,authenticated;

